import{A as e,H as t,V as n,et as r}from"./chunks/framework.B1PU1n-w.js";var i=JSON.parse(`{"title":"环境检查","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start/environment.md","filePath":"quick-start/environment.md"}`),a={name:`quick-start/environment.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="环境检查" tabindex="-1">环境检查 <a class="header-anchor" href="#环境检查" aria-label="Permalink to “环境检查”">​</a></h1><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>本篇内容面向 syncraft-server 使用者，即腐竹们。</p></div><h2 id="系统环境" tabindex="-1">系统环境 <a class="header-anchor" href="#系统环境" aria-label="Permalink to “系统环境”">​</a></h2><p>你的系统需要是 unix 类系统，Linux 和 MacOS 都是可以的。Windows 由于有各种服务和通信的困难，暂不受支持。</p><h2 id="网络环境" tabindex="-1">网络环境 <a class="header-anchor" href="#网络环境" aria-label="Permalink to “网络环境”">​</a></h2><p>除了用于你的 Minecraft 服务器的端口外，你的机器至少要再额外提供一个端口给 syncraft-server。如果你使用内网穿透开服，那么你也额外需要一条隧道，</p><p>另外，如果你使用我们的 mswrapper，你需要禁止它的端口被外部访问。</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>mswrapper 的端口直接暴露了服务器管理权限，务必保护起来。</p></div><h2 id="游戏实例" tabindex="-1">游戏实例 <a class="header-anchor" href="#游戏实例" aria-label="Permalink to “游戏实例”">​</a></h2><p>syncraft-server 并不劫持 Minecraft 服务器，它的运行与否和服务器的运行与否相互没有关系。但它确实需要一个已经安装好的服务器实例来初始化工作区。如果你的 Minecraft 服务器还没有安装，你完全可以先去启动它的安装再回来看文档。</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};